{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Rates — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff22;--accent:#7dd3fc;--muted:#cbd5e1;--bg:#0f172a;--card:#ffffff10}
    html,body{height:100%;margin:0;font-family:Inter,system-ui,Arial;background:linear-gradient(180deg,#07102a 0%, #071827 60%);color:#e6eef8}
    .site{min-height:100%;display:flex;flex-direction:column;background-image:url("assets/img/pattern.svg");background-repeat:repeat;}
    header{backdrop-filter:blur(6px);background:linear-gradient(90deg, rgba(255,255,255,0.03), rgba(255,255,255,0.01));padding:18px 28px;border-bottom:1px solid rgba(255,255,255,0.04)}
    .nav{display:flex;gap:18px;align-items:center;max-width:1100px;margin:0 auto}
    .brand{font-weight:700;letter-spacing:0.4px}
    nav a{color:var(--muted);text-decoration:none;padding:8px 12px;border-radius:8px}
    nav a.cta{background:linear-gradient(90deg,var(--accent),#60a5fa);color:#04263a;font-weight:600}
    main{flex:1;max-width:1100px;margin:28px auto;padding:0 20px}
    .hero{display:flex;gap:24px;align-items:center;padding:28px;border-radius:14px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));box-shadow:0 4px 32px rgba(2,6,23,0.6)}
    .hero .left{flex:1}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    /* Pricing cards */
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:22px}
    .card{padding:18px;border-radius:12px;background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.02));border:1px solid rgba(255,255,255,0.04)}
    .price{font-size:22px;font-weight:700;color:#e6f7ff}
    .muted{color:var(--muted);font-size:13px}

    /* Toggle */
    .toggle{display:inline-flex;align-items:center;background:var(--card);padding:6px;border-radius:999px;border:1px solid rgba(255,255,255,0.03)}
    .toggle button{background:transparent;border:0;color:var(--muted);padding:8px 12px;border-radius:999px;cursor:pointer}
    .toggle button.active{background:linear-gradient(90deg,var(--accent),#60a5fa);color:#04263a;font-weight:700}

    /* Proof gallery */
    .proof{margin-top:28px;padding:18px;border-radius:12px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03);display:flex;gap:16px;align-items:center}
    .testimony{flex:1}
    .quote{font-style:italic;color:#dff6ff}
    .badges{display:flex;gap:10px}
    .badge{position:relative;padding:8px 10px;border-radius:8px;background:#0b1a26;border:1px solid rgba(255,255,255,0.03);font-size:13px;color:var(--muted);cursor:default}
    .badge:hover{transform:translateY(-3px);transition:all .18s}
    .badge .tip{visibility:hidden;opacity:0;position:absolute;left:50%;transform:translateX(-50%) translateY(-8px);bottom:calc(100% + 8px);background:#021725;color:#dff6ff;padding:8px;border-radius:8px;font-size:12px;border:1px solid rgba(255,255,255,0.04);white-space:nowrap}
    .badge:hover .tip{visibility:visible;opacity:1}

    footer{padding:28px;text-align:center;color:var(--muted);font-size:13px}

    /* small responsive */
    @media (max-width:720px){.hero{flex-direction:column;align-items:flex-start}}

  </style>
</head>
<body>
  <div class="site">
    <header>
      <div class="nav">
        <div class="brand">{{BUSINESS_NAME}}</div>
        <nav style="margin-left:18px;flex:1">
          <a href="index.html">Welcome</a>
          <a href="services.html">Offerings</a>
          <a href="conditions.html">Conditions</a>
          <a href="approach.html">Our Path</a>
          <a href="pricing.html" style="color:#e6f7ff;font-weight:700">Rates</a>
          <a href="about.html">Story</a>
          <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        </nav>
        <div style="display:flex;gap:8px;align-items:center">
          <div class="muted">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
    </header>
    <main>
      <section class="hero">
        <div class="left">
          <h1>Flexible care, framed for your days</h1>
          <p class="lead">Choose a rhythm that fits — brief single sessions, steady monthly support, or a bundled series designed to review progress and adapt the plan.</p>
          <div style="margin-top:12px;font-size:14px">
            <span class="muted">Questions? </span><a href="contact.html" style="color:var(--accent);text-decoration:none;">Reach out</a>
          </div>
        </div>
        <div style="width:320px">
          <div style="background:rgba(255,255,255,0.02);padding:14px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px">
              <div class="muted">Billing view</div>
              <div class="toggle" role="tablist">
                <button id="monthlyBtn" class="active">Monthly</button>
                <button id="packageBtn">Package</button>
              </div>
            </div>
            <div class="card" style="margin:0">
              <div style="display:flex;justify-content:space-between;align-items:center">
                <div>
                  <div style="font-size:12px;color:var(--muted)">Monthly Nourish Plan</div>
                  <div class="muted">One 50-min visit + messaging</div>
                </div>
                <div style="text-align:right">
                  <div class="price" id="priceA">$120</div>
                  <div class="muted" style="font-size:12px">per month</div>
                </div>
              </div>
            </div>
            <div style="margin-top:10px;display:flex;gap:8px">
              <div class="card" style="flex:1">
                <div class="muted" style="font-size:12px">Intro Session</div>
                <div class="price" id="priceB">$95</div>
              </div>
              <div class="card" style="flex:1">
                <div class="muted" style="font-size:12px">Renewal Package (6)</div>
                <div class="price" id="priceC">$660</div>
              </div>
            </div>
          </div>
        </div>
      </section>

      <section style="margin-top:22px;display:flex;gap:18px;align-items:flex-start">
        <div style="flex:1">
          <h3 style="margin:0 0 8px 0">What these rates mean</h3>
          <p class="muted">Pricing reflects a focus on continuity and learning. Packages include planning and progress reviews. Nothing is obligatory — every plan can be adapted to your needs.</p>
          <div class="grid" style="margin-top:16px">
            <div class="card">
              <div style="font-weight:700">Single Visit</div>
              <div class="muted" style="margin-top:6px">A focused consultation and practical suggestions to try between visits.</div>
            </div>
            <div class="card">
              <div style="font-weight:700">Monthly Support</div>
              <div class="muted" style="margin-top:6px">Rhythm-based follow-up, brief check-ins, and adjustments as life shifts.</div>
            </div>
            <div class="card">
              <div style="font-weight:700">Course Package</div>
              <div class="muted" style="margin-top:6px">Curated sequence with outcome checkpoints and a wrap-up review.</div>
            </div>
          </div>
        </div>
        <aside style="width:320px">
          <div class="card">
            <div style="font-weight:700">Need help choosing?</div>
            <div class="muted" style="margin-top:8px">Book a 15-minute orientation call to align on goals and practical next steps.</div>
            <div style="margin-top:12px"><a class="cta" href="book.html" style="display:inline-block;padding:10px 12px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#60a5fa);color:#04263a;text-decoration:none">Reserve orientation</a></div>
          </div>
        </aside>
      </section>

      <section class="proof" aria-label="Proof gallery">
        <div style="width:72px;height:72px;border-radius:10px;background:linear-gradient(135deg,#052233,#063244);display:flex;align-items:center;justify-content:center;font-weight:700">P</div>
        <div class="testimony">
          <div class="quote" id="quoteText">"I finally felt like my day-to-day needs were seen and a sensible plan followed."</div>
          <div class="muted" style="margin-top:8px" id="quoteAuthor">— A client in {{CITY}}</div>
          <div class="badges" style="margin-top:12px">
            <div class="badge">Licensed Clinician<div class="tip">Board-certified practitioner with clinical training</div></div>
            <div class="badge">Community Choice<div class="tip">Voted community favorite for supportive care</div></div>
            <div class="badge">Press: Local Health<div class="tip">Featured in Local Health Magazine editorial</div></div>
          </div>
        </div>
        <div style="width:200px;text-align:right">
          <div style="font-size:13px;color:var(--muted)">Proof Gallery</div>
          <div style="margin-top:8px"><button id="prevT" style="padding:8px 10px;border-radius:8px;background:#081a25;border:0;color:var(--muted);cursor:pointer">◀</button> <button id="nextT" style="padding:8px 10px;border-radius:8px;background:#081a25;border:0;color:var(--muted);cursor:pointer">▶</button></div>
        </div>
      </section>

      <section style="margin-top:22px">
        <h4>Frequently asked</h4>
        <div class="grid" style="margin-top:10px">
          <div class="card"><div class="muted">Are treatments guaranteed?</div><div style="margin-top:6px;color:var(--muted)">Care is educational and supportive. We work together to design strategies; individual results vary.</div></div>
          <div class="card"><div class="muted">Do I need a referral?</div><div style="margin-top:6px;color:var(--muted)">No referral required. If useful, we coordinate with other professionals with your consent.</div></div>
        </div>
      </section>

      <section style="margin-top:26px;padding:18px;border-radius:12px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03)">
        <div style="display:flex;justify-content:space-between;align-items:center">
          <div>
            <div style="font-weight:700">Ready to pick a pace?</div>
            <div class="muted" style="margin-top:6px">Start with a single session or save with a curated package.</div>
          </div>
          <div><a href="book.html" class="cta" style="display:inline-block;padding:10px 14px;border-radius:10px;background:linear-gradient(90deg,var(--accent),#60a5fa);color:#04263a;text-decoration:none">{{PRIMARY_CTA_LABEL}}</a></div>
        </div>
      </section>

    </main>
    <footer>
      <div class="muted">Phone: <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a></div>
    </footer>
  </div>

  <script>
    // Pricing comparator with animated numbers
    (function(){
      const monthlyBtn = document.getElementById('monthlyBtn');
      const packageBtn = document.getElementById('packageBtn');
      const priceA = document.getElementById('priceA');
      const priceB = document.getElementById('priceB');
      const priceC = document.getElementById('priceC');

      const monthly = {a:120,b:95,c:660};
      const pack = {a:105*6/1,b:85,c:540}; // presented as alternative math

      let current = monthly;

      function animateNumber(el, start, end, duration){
        const startTime = performance.now();
        function tick(now){
          const t = Math.min(1,(now - startTime)/duration);
          const val = Math.round(start + (end-start)*t);
          el.textContent = '$' + val;
          if(t < 1) requestAnimationFrame(tick);
        }
        requestAnimationFrame(tick);
      }

      function setView(view){
        monthlyBtn.classList.toggle('active', view === 'monthly');
        packageBtn.classList.toggle('active', view === 'package');
        const next = view === 'monthly' ? monthly : pack;
        animateNumber(priceA, parseInt(priceA.textContent.replace('$','')) || 0, Math.round(next.a), 450);
        animateNumber(priceB, parseInt(priceB.textContent.replace('$','')) || 0, Math.round(next.b), 450);
        animateNumber(priceC, parseInt(priceC.textContent.replace('$','')) || 0, Math.round(next.c), 450);
        current = next;
      }

      monthlyBtn.addEventListener('click', ()=>setView('monthly'));
      packageBtn.addEventListener('click', ()=>setView('package'));
    })();

    // Proof gallery rotate and controls
    (function(){
      const quotes = [
        {text:'"I finally felt like my day-to-day needs were seen and a sensible plan followed."',author:'— A client in '+('{{CITY}}')},
        {text:'"The package helped me track progress and tweak what wasn\'t working with gentle adjustments."',author:'— Someone who completed a course'},
        {text:'"Warm, practical guidance that I could actually apply between visits."',author:'— Community member'}
      ];
      let idx = 0;
      const quoteText = document.getElementById('quoteText');
      const quoteAuthor = document.getElementById('quoteAuthor');
      const prevBtn = document.getElementById('prevT');
      const nextBtn = document.getElementById('nextT');

      function show(i){
        idx = (i + quotes.length) % quotes.length;
        quoteText.style.opacity = 0;
        quoteAuthor.style.opacity = 0;
        setTimeout(()=>{
          quoteText.textContent = quotes[idx].text;
          quoteAuthor.textContent = quotes[idx].author;
          quoteText.style.opacity = 1;
          quoteAuthor.style.opacity = 1;
        },200);
      }

      prevBtn.addEventListener('click', ()=>show(idx-1));
      nextBtn.addEventListener('click', ()=>show(idx+1));

      let auto = setInterval(()=>show(idx+1),5000);
      [prevBtn,nextBtn].forEach(b=>b.addEventListener('mouseenter', ()=>clearInterval(auto)));
      [prevBtn,nextBtn].forEach(b=>b.addEventListener('mouseleave', ()=>auto = setInterval(()=>show(idx+1),5000)));

      show(0);
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Our Story — {{BUSINESS_NAME}}</title>
  <style>
    :root{--glass:#ffffff16;--accent:#9ae6b4;--muted:#cbd5e1;--bg:#071024}
    body{margin:0;font-family:Inter,system-ui,Arial;background:linear-gradient(180deg,#04192a 0%, #071827 60%);color:#e8f8ff}
    .wrap{max-width:1000px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center;padding:12px 0}
    .nav a{color:var(--muted);text-decoration:none;margin-right:12px}
    .nav a.active{color:var(--accent);font-weight:700}
    .card{background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
    h1{margin:0 0 6px 0}
    .lead{color:var(--muted);margin-top:0}
    .team{display:flex;gap:12px;margin-top:16px}
    .member{flex:1;background:rgba(255,255,255,0.02);padding:12px;border-radius:10px}
    .member h4{margin:0 0 6px 0}

    /* proof gallery big */
    .proof-large{margin-top:18px;padding:12px;border-radius:12px;display:flex;gap:12px;align-items:center}
    .media{width:120px;height:120px;border-radius:12px;background:linear-gradient(135deg,#042a27,#063a36);display:flex;align-items:center;justify-content:center;font-weight:700}
    .testimony{flex:1}
    .quote{font-style:italic;color:#dfffe6}
    .controls{display:flex;gap:10px}
    .badge{padding:6px 8px;border-radius:8px;background:#081f1a;color:var(--muted);font-size:13px}

    footer{margin-top:22px;color:var(--muted);font-size:13px}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <nav class="nav">
          <a href="index.html">Home</a>
          <a href="services.html">Offerings</a>
          <a href="pricing.html">Rates</a>
          <a href="about.html" class="active">Story</a>
          <a href="book.html">Schedule</a>
        </nav>
      </div>
      <div><a href="mailto:{{EMAIL}}" style="color:var(--muted);text-decoration:none">{{EMAIL}}</a></div>
    </header>

    <section class="card">
      <h1>Why this way of care?</h1>
      <p class="lead">We combine clinical training with practical rituals you can roll into everyday life. Our approach aims to map your priorities into a plan that respects your time and values.</p>
      <div style="margin-top:12px;display:flex;gap:12px">
        <div style="flex:1">
          <h4 style="margin:0 0 6px 0">Origins</h4>
          <p class="muted">Founded by clinicians who wanted care to be clearer and easier to act on, with measurement points rather than vague check-ins.</p>
        </div>
        <div style="width:220px">
          <div style="background:rgba(255,255,255,0.02);padding:12px;border-radius:10px;text-align:center">
            <div style="font-weight:700">Hours</div>
            <div class="muted">Available by appointment</div>
            <div style="margin-top:8px"><a href="book.html" style="text-decoration:none;background:linear-gradient(90deg,var(--accent),#60f5c3);color:#05221a;padding:8px 12px;border-radius:8px">Book time</a></div>
          </div>
        </div>
      </div>
    </section>

    <section class="card" style="margin-top:18px">
      <h3 style="margin:0 0 8px 0">The team</h3>
      <div class="team">
        <div class="member">
          <h4>Lead Clinician</h4>
          <div class="muted">Clinical background with training in integrative approaches and patient-centered planning.</div>
        </div>
        <div class="member">
          <h4>Collaborative Practitioners</h4>
          <div class="muted">A small network of allied professionals we coordinate with when topics require specialty input.</div>
        </div>
      </div>
    </section>

    <section class="proof-large card" aria-label="Testimonials and credibility">
      <div class="media">S</div>
      <div class="testimony">
        <div class="quote" id="bigQuote">"Warm, practical guidance that fit into my routine."</div>
        <div class="muted" id="bigAuthor">— Local client</div>
        <div style="margin-top:12px;display:flex;gap:8px" id="credWrap">
          <div class="badge" data-tip="Awarded by community wellness collective">Community Award</div>
          <div class="badge" data-tip="Clinical registry listing">Professional Registry</div>
          <div class="badge" data-tip="Mention in regional health column">Press Mention</div>
        </div>
      </div>
      <div class="controls">
        <button id="prevLarge" style="padding:8px;border-radius:8px;background:#071a18;border:0;color:var(--muted)">Prev</button>
        <button id="nextLarge" style="padding:8px;border-radius:8px;background:#071a18;border:0;color:var(--muted)">Next</button>
      </div>
    </section>

    <section style="margin-top:18px" class="card">
      <h4 style="margin:0 0 6px 0">A note on scope</h4>
      <p class="muted">This site provides educational information and supportive care options. It is not a promise of a cure. We encourage conversations with your primary care team when needed.</p>
    </section>

    <footer>
      <div style="margin-top:12px">Phone: <a href="tel:{{PHONE}}" style="color:var(--muted);text-decoration:none">{{PHONE}}</a> • <a href="book.html" style="color:var(--muted);text-decoration:none">Schedule a visit</a></div>
    </footer>
  </div>

  <script>
    // Proof gallery rotate (large)
    (function(){
      const items = [
        {q:'"Warm, practical guidance that fit into my routine."',a:'— Local client'},
        {q:'"A steady plan helped me test ideas and keep what worked."',a:'— Participant'},
        {q:'"They explained risks and options clearly and without pressure."',a:'— Community member'}
      ];
      let i = 0;
      const qEl = document.getElementById('bigQuote');
      const aEl = document.getElementById('bigAuthor');
      const prev = document.getElementById('prevLarge');
      const next = document.getElementById('nextLarge');

      function show(n){
        i = (n + items.length) % items.length;
        qEl.style.opacity = 0; aEl.style.opacity = 0;
        setTimeout(()=>{ qEl.textContent = items[i].q; aEl.textContent = items[i].a; qEl.style.opacity=1; aEl.style.opacity=1; },180);
      }
      prev.addEventListener('click', ()=>show(i-1));
      next.addEventListener('click', ()=>show(i+1));
      let t = setInterval(()=>show(i+1),6000);
      [prev,next].forEach(b=>{ b.addEventListener('mouseenter', ()=>clearInterval(t)); b.addEventListener('mouseleave', ()=>t=setInterval(()=>show(i+1),6000)); });
    })();

    // Badge tooltips (simple)
    (function(){
      const wrap = document.getElementById('credWrap');
      Array.from(wrap.children).forEach(el=>{
        const tip = document.createElement('div');
        tip.textContent = el.getAttribute('data-tip');
        tip.style.position='absolute';tip.style.background='#021514';tip.style.color='#dfffe6';tip.style.padding='6px 8px';tip.style.borderRadius='8px';tip.style.fontSize='12px';tip.style.visibility='hidden';tip.style.opacity='0';tip.style.transition='all .12s';
        el.style.position='relative';
        el.appendChild(tip);
        el.addEventListener('mouseenter', ()=>{ tip.style.visibility='visible'; tip.style.opacity='1'; tip.style.transform='translateY(-6px)'; });
        el.addEventListener('mouseleave', ()=>{ tip.style.visibility='hidden'; tip.style.opacity='0'; tip.style.transform='translateY(0)'; });
      });
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Schedule — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#041022;--glass:#ffffff14;--accent:#ffd6a5;--muted:#bcd0da}
    body{margin:0;font-family:Inter,system-ui,Arial;background:linear-gradient(180deg,#021522,#041022);color:#eaf8ff}
    .wrap{max-width:900px;margin:28px auto;padding:18px}
    header{display:flex;justify-content:space-between;align-items:center}
    .nav a{color:var(--muted);text-decoration:none;margin-left:12px}
    .hero{padding:18px;border-radius:12px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));border:1px solid rgba(255,255,255,0.03)}
    form{margin-top:14px;display:grid;grid-template-columns:1fr 280px;gap:12px}
    .field{margin-bottom:10px}
    label{display:block;font-size:13px;color:var(--muted);margin-bottom:6px}
    input,textarea,select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(255,255,255,0.03);background:rgba(255,255,255,0.02);color:#e8fbff}
    button{padding:10px 12px;border-radius:10px;border:0;background:linear-gradient(90deg,var(--accent),#ffb4a2);color:#2b1b0f;font-weight:700;cursor:pointer}
    .small{font-size:13px;color:var(--muted)}
    .proof{margin-top:18px;display:flex;gap:12px;align-items:center}

    @media (max-width:820px){form{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <div class="wrap">
    <header>
      <div style="display:flex;align-items:center;gap:12px">
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <nav class="nav">
